protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, 
                          @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, 
                          boolean speculative) {
    if (debug) {
        System.out.println("closure(" + config.toString(recog, true) + ")");
    }

    if (config.state instanceof RuleStopState) {
        logRuleStopState(config);

        if (isContextEmpty(config.context)) {
            configs.add(config);
            return true;
        } else {
            handleNonEmptyContext(config, configs);
        }

        return processContext(config, input, configs, currentAltReachedAcceptState, speculative);
    }

    optimizeConfig(configs, currentAltReachedAcceptState, config);

    return processTransitions(input, config, configs, currentAltReachedAcceptState, speculative);
}

private void logRuleStopState(LexerATNConfig config) {
    if (debug) {
        if (recog != null) {
            System.out.format("closure at %s rule stop %s\
", recog.getRuleNames()[config.state.ruleIndex], config);
        } else {
            System.out.format("closure at rule stop %s\
", config);
        }
    }
}

private boolean isContextEmpty(PredictionContext context) {
    return context == null || context.hasEmptyPath() || context.isEmpty();
}

private void handleNonEmptyContext(LexerATNConfig config, ATNConfigSet configs) {
    configs.add(new LexerATNConfig(config, config.state, PredictionContext.EMPTY));
}

private boolean processContext(LexerATNConfig config, CharStream input, ATNConfigSet configs, 
                               boolean currentAltReachedAcceptState, boolean speculative) {
    if (config.context != null && !config.context.isEmpty()) {
        for (SingletonPredictionContext ctx : config.context) {
            if (!ctx.isEmpty()) {
                currentAltReachedAcceptState = handleContextEntry(config, input, configs, currentAltReachedAcceptState, ctx);
            }
        }
    }
    return currentAltReachedAcceptState;
}

private boolean handleContextEntry(LexerATNConfig config, CharStream input, ATNConfigSet configs, 
                                    boolean currentAltReachedAcceptState, SingletonPredictionContext ctx) {
    PredictionContext newContext = ctx.parent; // "pop" return state
    if (ctx.returnState == PredictionContext.EMPTY_RETURN_STATE) {
        recordEndState(configs, config, ctx);
    } else {
        ATNState returnState = atn.states.get(ctx.returnState);
        LexerATNConfig newConfig = new LexerATNConfig(returnState, config.alt, newContext);
        currentAltReachedAcceptState = closure(input, newConfig, configs, currentAltReachedAcceptState, speculative);
    }
    return currentAltReachedAcceptState;
}

private void recordEndState(ATNConfigSet configs, LexerATNConfig config, SingletonPredictionContext ctx) {
    LexerATNConfig endConfig = new LexerATNConfig(config, config.state, ctx);
    if (debug) {
        System.out.println("FALLING off token " + 
                           recog.getRuleNames()[config.state.ruleIndex] + 
                           " record " + endConfig);
    }
    configs.add(endConfig);
}

private void optimizeConfig(ATNConfigSet configs, boolean currentAltReachedAcceptState, LexerATNConfig config) {
    if (!config.state.onlyHasEpsilonTransitions() && 
        (!currentAltReachedAcceptState || !config.hasPassedThroughNonGreedyDecision())) {
        configs.add(config);
    }
}

private boolean processTransitions(CharStream input, LexerATNConfig config, ATNConfigSet configs, 
                                   boolean currentAltReachedAcceptState, boolean speculative) {
    ATNState state = config.state;
    for (int i = 0; i < state.getNumberOfTransitions(); i++) {
        Transition transition = state.transition(i);
        LexerATNConfig newConfig = getEpsilonTarget(input, config, transition, configs, speculative);
        if (newConfig != null) {
            currentAltReachedAcceptState = closure(input, newConfig, configs, currentAltReachedAcceptState, speculative);
        }
    }
    return currentAltReachedAcceptState;
}

protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, boolean speculative) {
    if (debug) {
        System.out.println("closure("+config.toString(recog, true)+")");
    }

    if (config.state instanceof RuleStopState) {
        if (debug) {
            if (recog != null) {
                System.out.format("closure at %s rule stop %s\
", recog.getRuleNames()[config.state.ruleIndex], config);
            } else {
                System.out.format("closure at rule stop %s\
", config);
            }
        }

        if (isUnknownContext(config.context)) {
            configs.add(config);
            return true;
        } else {
            configs.add(new LexerATNConfig(config, config.state, PredictionContext.EMPTY));
            currentAltReachedAcceptState = true;
        }

        if (config.context != null && !config.context.isEmpty()) {
            for (SingletonPredictionContext ctx : config.context) {
                if (!ctx.isEmpty()) {
                    PredictionContext newContext = ctx.parent; // "pop" return state
                    if (ctx.returnState == PredictionContext.EMPTY_RETURN_STATE) {
                        // we have no context info. Don\'t pursue but record a special configuration.
                        LexerATNConfig c = new LexerATNConfig(config, config.state, ctx);
                        if (debug) 
                            System.out.println("FALLING off token "+recog.getRuleNames()[config.state.ruleIndex]+" record "+c);
                        configs.add(c);
                        continue;
                    }
                    ATNState returnState = atn.states.get(ctx.returnState);
                    LexerATNConfig c = new LexerATNConfig(returnState, config.alt, newContext);
                    currentAltReachedAcceptState = closure(input, c, configs, currentAltReachedAcceptState, speculative);
                }
            }
        }

        return currentAltReachedAcceptState;
    }

    // optimization
    if (!config.state.onlyHasEpsilonTransitions()) {
        if (!currentAltReachedAcceptState || !config.hasPassedThroughNonGreedyDecision()) {
            configs.add(config);
        }
    }

    ATNState p = config.state;
    for (int i = 0; i < p.getNumberOfTransitions(); i++) {
        Transition t = p.transition(i);
        LexerATNConfig c = getEpsilonTarget(input, config, t, configs, speculative);
        if (c != null) {
            currentAltReachedAcceptState = closure(input, c, configs, currentAltReachedAcceptState, speculative);
        }
    }

    return currentAltReachedAcceptState;
}

private boolean isUnknownContext(PredictionContext context) {
    return context == null || context.isEmpty();
}

