public String asString() {
    if (start == null) {
        return null;
    }

    marked = new HashSet<>();
    work = new ArrayList<>();
    work.add(start);

    StringBuilder buf = new StringBuilder();

    while (!work.isEmpty()) {
        ATNState state = work.remove(0);
        if (marked.contains(state)) {
            continue;
        }

        marked.add(state);
        int transitionsCount = state.getNumberOfTransitions();

        for (int i = 0; i < transitionsCount; i++) {
            Transition transition = state.transition(i);
            processTransition(transition, state, buf);

            if (!(state instanceof RuleStopState)) {
                if (transition instanceof RuleTransition) {
                    work.add(((RuleTransition) transition).followState);
                } else {
                    work.add(transition.target);
                }
            }
        }
    }
    return buf.toString();
