private void processTransition(Transition transition, ATNState state, StringBuilder buf) {
    buf.append(getStateString(state));

    if (transition instanceof EpsilonTransition) {
        buf.append("->").append(getStateString(transition.target)).append(\'\
\');
    } else if (transition instanceof RuleTransition) {
        buf.append("-").append(g.getRule(((RuleTransition) transition).ruleIndex).name)
           .append("->").append(getStateString(transition.target)).append(\'\
\');
    } else if (transition instanceof ActionTransition) {
        buf.append("-").append(transition.toString()).append("->").append(getStateString(transition.target)).append(\'\
\');
    } else if (transition instanceof SetTransition) {
        appendSetTransitionDetails((SetTransition) transition, buf);
    } else if (transition instanceof AtomTransition) {
        String label = g.getTokenDisplayName(((AtomTransition) transition).label);
        buf.append("-").append(label).append("->").append(getStateString(transition.target)).append(\'\
\');
    } else {
        buf.append("-").append(transition.toString()).append("->").append(getStateString(transition.target)).append(\'\
\');
    }
}

private void appendSetTransitionDetails(SetTransition transition, StringBuilder buf) {
