private void processTransitions(ATNState s, StringBuilder buf) {
    int n = s.getNumberOfTransitions();
    for (int i = 0; i < n; i++) {
        Transition t = s.transition(i);
        if (!(s instanceof RuleStopState)) {
            addToWork(t);
        }
        appendTransitionString(buf, s, t);
    }
}

