            captureSimState(prevAccept, input, target);
            if (t == IntStream.EOF) {
                break;
            }
        }

        if (t != IntStream.EOF) {
            consume(input);
            t = input.LA(1);
        }

        currentState = target;
    }

    return failOrAccept(prevAccept, input, currentState.configs, t);
}

private DFAState getTargetState(DFAState currentState, int t) {
    if (currentState.edges != null && t >= MIN_DFA_EDGE && t <= MAX_DFA_EDGE) {
        DFAState target = currentState.edges[t - MIN_DFA_EDGE];
        if (target != ERROR) {
            if (debug) {
                System.out.println("reuse state " + currentState.stateNumber + " edge to " + target.stateNumber);
            }
            return target;
        }
    }
    return null;
}

protected int execATN(@NotNull CharStream input, @NotNull DFAState ds0) {
    int t = input.LA(1);
    @NotNull DFAState s = ds0; // s is current/from DFA state

    while (true) { // while more work
        ATNConfigSet closure = s.configs;
        DFAState target = getTargetDFAState(s, t);

        if (target == null) {
            ATNConfigSet reach = new OrderedATNConfigSet();
            getReachableConfigSet(input, closure, reach, t);

            if (reach.isEmpty()) {
                @NotNull DFAState from = s != null ? s : addDFAState(closure);
                addDFAEdge(from, t, ERROR);
                break; // stop when we can't match any more char
            }

            target = addDFAEdge(s, t, reach);
        }

        if (target.isAcceptState) {
            captureSimState(prevAccept, input, target);
            if (t == IntStream.EOF) {
                break;
            }
        }

        if (t != IntStream.EOF) {
            consume(input);
            t = input.LA(1);
        }

        s = target; // flip; current DFA target becomes new src/from state
    }

    return failOrAccept(prevAccept, input, s.configs, t);
}

private DFAState getTargetDFAState(DFAState s, int t) {
    if (s.edges != null && t >= MIN_DFA_EDGE && t <= MAX_DFA_EDGE) {
        DFAState target = s.edges[t - MIN_DFA_EDGE];
        if (target != ERROR) {
            return target;
        }
    }
    return null;
}

