protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, 
                            @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, 
                            boolean speculative) {
    logDebugClosure(config);

    if (config.state instanceof RuleStopState) {
        handleRuleStopState(config, configs);
        return handleContext(config, configs, currentAltReachedAcceptState);
    }

    optimizeConfigIfNeeded(currentAltReachedAcceptState, config, configs);
    return processTransitions(input, config, configs, currentAltReachedAcceptState, speculative);
}

private void logDebugClosure(LexerATNConfig config) {
    if (debug) {
        System.out.println("closure(" + config.toString(recog, true) + ")");
    }
}

private void handleRuleStopState(LexerATNConfig config, ATNConfigSet configs) {
    if (debug) {
        printDebugRuleStopInfo(config);
    }

    if (config.context == null || config.context.hasEmptyPath()) {
        handleEmptyContext(config, configs);
    }
}

private void printDebugRuleStopInfo(LexerATNConfig config) {
    String ruleName = recog != null ? recog.getRuleNames()[config.state.ruleIndex] : "";
    System.out.format("closure at %s rule stop %s%n", ruleName, config);
}

private void handleEmptyContext(LexerATNConfig config, ATNConfigSet configs) {
    if (config.context == null || config.context.isEmpty()) {
        configs.add(config);
    } else {
        configs.add(new LexerATNConfig(config, config.state, PredictionContext.EMPTY));
    }
}

private boolean handleContext(LexerATNConfig config, ATNConfigSet configs, boolean currentAltReachedAcceptState) {
    if (config.context != null && !config.context.isEmpty()) {
        for (SingletonPredictionContext ctx : config.context) {
            if (!ctx.isEmpty()) {
                currentAltReachedAcceptState = processReturnState(config, ctx, configs, currentAltReachedAcceptState);
            }
        }
    }
    return currentAltReachedAcceptState;
}

private boolean processReturnState(LexerATNConfig config, SingletonPredictionContext ctx, 
                                    ATNConfigSet configs, boolean currentAltReachedAcceptState) {
    PredictionContext newContext = ctx.parent; // "pop" return state
    if (ctx.returnState == PredictionContext.EMPTY_RETURN_STATE) {
        recordEndOfToken(config, ctx, configs);
        return currentAltReachedAcceptState;
    }
    ATNState returnState = atn.states.get(ctx.returnState);
    LexerATNConfig c = new LexerATNConfig(returnState, config.alt, newContext);
    return closure(input, c, configs, currentAltReachedAcceptState, speculative);
}

private void recordEndOfToken(LexerATNConfig config, SingletonPredictionContext ctx, ATNConfigSet configs) {
    LexerATNConfig recordConfig = new LexerATNConfig(config, config.state, ctx);
    if (debug) {
        System.out.println("FALLING off token " + recog.getRuleNames()[config.state.ruleIndex] + " record " + recordConfig);
    }
    configs.add(recordConfig);
}

private void optimizeConfigIfNeeded(boolean currentAltReachedAcceptState, LexerATNConfig config, ATNConfigSet configs) {
    if (!config.state.onlyHasEpsilonTransitions()) {
        if (!currentAltReachedAcceptState || !config.hasPassedThroughNonGreedyDecision()) {
            configs.add(config);
        }
    }
}

private boolean processTransitions(CharStream input, LexerATNConfig config, ATNConfigSet configs,
                                    boolean currentAltReachedAcceptState, boolean speculative) {
    ATNState state = config.state;
    for (int i = 0; i < state.getNumberOfTransitions(); i++) {
        Transition transition = state.transition(i);
        LexerATNConfig nextConfig = getEpsilonTarget(input, config, transition, configs, speculative);
        if (nextConfig != null) {
            currentAltReachedAcceptState = closure(input, nextConfig, configs, currentAltReachedAcceptState, speculative);
        }
    }
    return currentAltReachedAcceptState;
}

