protected boolean closure(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, boolean speculative) {
    if (debug) {
        System.out.println("closure(" + config.toString(recog, true) + ")");
    }

    if (config.state instanceof RuleStopState) {
        handleRuleStopState(input, config, configs, currentAltReachedAcceptState, speculative);
    } else {
        handleNonRuleStopState(config, configs, currentAltReachedAcceptState);
    }

    return currentAltReachedAcceptState;
}

private void handleRuleStopState(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs, boolean currentAltReachedAcceptState, boolean speculative) {
    if (debug) {
        logRuleStopState(config);
    }

    if (config.context == null || config.context.hasEmptyPath()) {
        handleEmptyContext(config, configs);
    }

    if (config.context != null && !config.context.isEmpty()) {
        for (SingletonPredictionContext ctx : config.context) {
            processSingletonPredictionContext(input, config, configs, ctx);
        }
    }
}

private void logRuleStopState(@NotNull LexerATNConfig config) {
    if (recog != null) {
