}

private void processSingletonPredictionContext(@NotNull CharStream input, @NotNull LexerATNConfig config, @NotNull ATNConfigSet configs, SingletonPredictionContext ctx) {
    if (!ctx.isEmpty()) {
        PredictionContext newContext = ctx.parent; // "pop" return state
        if (ctx.returnState == PredictionContext.EMPTY_RETURN_STATE) {
            recordConfig(config, ctx, configs);
        } else {
            ATNState returnState = atn.states.get(ctx.returnState);
            LexerATNConfig newConfig = new LexerATNConfig(returnState, config.alt, newContext);
            closure(input, newConfig, configs, currentAltReachedAcceptState, speculative);
        }
    }
}

private void recordConfig(@NotNull LexerATNConfig config, SingletonPredictionContext ctx, @NotNull ATNConfigSet configs) {
    LexerATNConfig c = new LexerATNConfig(config, config.state, ctx);
    if (debug) {
        System.out.println("FALLING off token " +
